export default JSON.parse("{\"metadata\":{\"schema\":\"universal.time-conversion.v2\",\"title\":\"Universal Time, Calendar, UTC, and Era Conversion\",\"version\":\"2.0.0-timezone-encounters\",\"terminology\":{\"dungeon_master\":\"Dungeon Master\",\"abbreviation\":\"DM\"},\"purpose\":\"Conversions among rounds, Beats, rests, journeys, downtime, projects, campaign years, and WorldBuilder eras.\",\"source_package\":\"Universal_5_5e_Campaign_System_v1\",\"references\":[\"universal_how_to_play.json\",\"universal_factions_and_quest_hooks.json\"]},\"play_time_scales\":[{\"mode\":\"Free Play\",\"scale\":\"seconds to hours\",\"procedure\":\"Conversation and tests as needed\"},{\"mode\":\"Conflict\",\"scale\":\"six-second rounds\",\"procedure\":\"Initiative, 3 Beats, Reactions\"},{\"mode\":\"Challenge\",\"scale\":\"flexible turns\",\"procedure\":\"Progress and Danger clocks\"},{\"mode\":\"Journey\",\"scale\":\"watches or days\",\"procedure\":\"Route choices, roles, Supply, hazard clocks\"},{\"mode\":\"Downtime\",\"scale\":\"days to months\",\"procedure\":\"Projects, recovery, faction and settlement turns\"},{\"mode\":\"Legacy\",\"scale\":\"months to years\",\"procedure\":\"Institutions, era change, world-scale clocks\"}],\"combat_time\":{\"round_seconds\":6,\"beats_per_turn\":3,\"reaction_window\":\"From the end of a creature's turn until the start of its next turn.\",\"fifth_edition_action_translation\":{\"movement_up_to_speed\":1,\"action\":2,\"bonus_action_swift\":1,\"action_plus_bonus_action\":3,\"reaction\":\"Reaction\",\"free_object_interaction\":\"once per turn\"}},\"rests\":{\"breather\":{\"duration\":\"1 minute\",\"benefit\":\"spend one Hit Die or clear 1 Stress\",\"limit\":\"once per Field Rest\"},\"field\":{\"duration\":\"10 minutes\",\"benefits\":[\"spend Hit Dice\",\"restore Guard\",\"short-rest features\",\"limited Stress recovery\"]},\"haven\":{\"duration\":\"8 hours\",\"benefits\":[\"long-rest resources\",\"half spent Hit Dice\",\"heal to half HP then spend Hit Dice\",\"clear ordinary Stress\"]},\"recuperation\":{\"duration\":\"1+ days\",\"benefits\":[\"Wound recovery\",\"Fracture treatment\",\"Scar projects\",\"full repair\"]}},\"journey_time\":{\"unit\":\"watch or travel day, chosen to match the fiction\",\"supply\":\"1 Supply supports 1 character for 1 travel day or one party requirement.\",\"paces\":{\"cautious\":\"Edge on hazard tests; uses 2 Supply\",\"steady\":\"Uses 1 Supply\",\"urgent\":\"Fill 1 Progress and 1 Danger; prevents a full Field Rest\"}},\"downtime\":{\"default_turn\":\"1 week\",\"actions_per_character\":2,\"intensive_actions\":1},\"project_scales\":{\"personal\":{\"clock\":4},\"group\":{\"clock\":6},\"settlement\":{\"clock\":8},\"regional\":{\"clock\":12},\"planetary_or_era\":{\"clock\":\"linked 12-segment clocks\"}},\"campaign_years\":{\"meaning\":\"Pacing windows, not scheduled outcomes.\",\"flexibility\":[\"combine\",\"delay\",\"reorder\",\"extend\",\"omit\"],\"advancement_note\":\"Era change is a Legacy-scale project rather than an instant global rewrite.\"},\"worldbuilder_era_scale\":{\"0\":{\"label\":\"Stone Age\"},\"1\":{\"label\":\"Early Metallurgy\"},\"2\":{\"label\":\"Iron / Classical\"},\"3\":{\"label\":\"Medieval\"},\"4\":{\"label\":\"Renaissance / Early Modern\"},\"5\":{\"label\":\"Industrial / Steam\"},\"6\":{\"label\":\"Electrified / Modern\"},\"7\":{\"label\":\"Digital / Atomic\"},\"8\":{\"label\":\"Planetary / Orbital\"},\"9\":{\"label\":\"Interplanetary\"},\"10\":{\"label\":\"Spacefaring / Interstellar\"}},\"era_meaning\":\"Common access, infrastructure, training, replacement parts, and social assumptions\u2014not personal worth or automatic combat superiority.\",\"era_transition_tracks\":[\"Discovery\",\"Infrastructure\",\"Access\",\"Social Adoption\"],\"local_variation\":\"Settlements may combine technologies from different eras; the global Era is a common ceiling, not compulsory uniformity.\",\"era_equipment_rules\":[{\"id\":\"12_2_function_profiles\",\"title\":\"Function profiles\",\"blocks\":[{\"type\":\"paragraph\",\"text\":\"Build weapons from function rather than historical name.\"},{\"type\":\"table\",\"columns\":[\"Profile\",\"Damage\",\"Properties\"],\"rows\":[{\"Profile\":\"Light\",\"Damage\":\"1d6\",\"Properties\":\"Concealable, finesse or thrown\"},{\"Profile\":\"Standard\",\"Damage\":\"1d8\",\"Properties\":\"One-handed or versatile\"},{\"Profile\":\"Heavy\",\"Damage\":\"1d10\",\"Properties\":\"Two-handed, forceful\"},{\"Profile\":\"Great\",\"Damage\":\"2d6\",\"Properties\":\"Two-handed, bulky\"},{\"Profile\":\"Sidearm\",\"Damage\":\"1d8\",\"Properties\":\"Ranged, Near/Far, reload\"},{\"Profile\":\"Longarm\",\"Damage\":\"1d10\",\"Properties\":\"Ranged, Far/Distant, two-handed, reload\"},{\"Profile\":\"Scatter\",\"Damage\":\"2d6\",\"Properties\":\"Near, two-handed, reload; one Burden at Far\"},{\"Profile\":\"Precision\",\"Damage\":\"1d12\",\"Properties\":\"Far/Distant, aim, two-handed, reload\"}]},{\"type\":\"paragraph\",\"text\":\"A sword, vibroblade, fossil-tooth macuahuitl, and bounded plasma cutter can use the same profile with different tags. Superior technology changes access, range, armor interaction, sensors, maintenance, and Scale before it changes bounded personal damage.\"}],\"number\":\"12.2\"},{\"id\":\"12_3_tags\",\"title\":\"Tags\",\"blocks\":[{\"type\":\"paragraph\",\"text\":\"Common tags include Aim, Arc, Automatic, Blast, Breach, Concealable, Defensive, Finesse, Forceful, Heavy, Integrated, Nonlethal, Reach, Reload, Silent, Thrown, Two-Handed, Unstable, and Versatile.\"},{\"type\":\"unordered_list\",\"items\":[\"Aim: spend 1 Beat without moving to gain one Edge on the next attack this turn.\",\"Automatic: spend 1 Supply or charge to Suppress a Near zone.\",\"Blast: affects a Near point and adjacent Engaged targets; targets save for half if the effect permits.\",\"Breach: counts as one Scale higher against objects, cover, and vehicles, not creatures.\",\"Defensive: while wielded, Guard action also grants +1 Guard until next turn.\",\"Forceful: on a Forceful Hit, push 10 feet instead of 5.\",\"Reload: after a number of attacks set by the item, spend 1 Beat and ammunition/charge.\",\"Unstable: a Crisis adds one Wear or Instability.\"]}],\"number\":\"12.3\"},{\"id\":\"12_4_armor_profiles\",\"title\":\"Armor profiles\",\"blocks\":[{\"type\":\"table\",\"columns\":[\"Armor\",\"Base AC\",\"Guard\",\"Common limits\"],\"rows\":[{\"Armor\":\"Light\",\"Base AC\":\"11 + Dex\",\"Guard\":\"1\",\"Common limits\":\"Minimal\"},{\"Armor\":\"Medium\",\"Base AC\":\"13 + Dex, max +2\",\"Guard\":\"2\",\"Common limits\":\"Stealth Burden for some suits\"},{\"Armor\":\"Heavy\",\"Base AC\":\"16\",\"Guard\":\"3\",\"Common limits\":\"Strength or power requirement; Stealth Burden\"},{\"Armor\":\"Shield\",\"Base AC\":\"+2 AC\",\"Guard\":\"+1\",\"Common limits\":\"Occupies hand or mount\"},{\"Armor\":\"Powered shell\",\"Base AC\":\"16\u201318\",\"Guard\":\"3\",\"Common limits\":\"Requires charge, maintenance, and Era access\"}]},{\"type\":\"paragraph\",\"text\":\"Specific class dossiers or items may use familiar fifth-edition armor values. Choose one calculation; do not stack base AC formulas.\"}],\"number\":\"12.4\"},{\"id\":\"12_5_wealth_availability_and_supply\",\"title\":\"Wealth, Availability, and Supply\",\"blocks\":[{\"type\":\"paragraph\",\"text\":\"Use familiar coinage for ordinary purchases where it helps, but rare gear requires Availability as well as price.\"},{\"type\":\"table\",\"columns\":[\"Availability\",\"Meaning\"],\"rows\":[{\"Availability\":\"Common\",\"Meaning\":\"Ordinary local purchase\"},{\"Availability\":\"Controlled\",\"Meaning\":\"License, guild, faction, or professional access\"},{\"Availability\":\"Restricted\",\"Meaning\":\"Mission, black market, state, temple, or military authority\"},{\"Availability\":\"Unique\",\"Meaning\":\"Project, discovery, patron, or story reward\"}]},{\"type\":\"paragraph\",\"text\":\"Supply abstracts ammunition, charge packs, consumable components, ordinary spare parts, and expedition necessities. A character carries PB Supply without using slots; extra Supply uses one carry slot each.\"}],\"number\":\"12.5\"}],\"world_clock\":{\"authority\":\"Universal uses Earth UTC as the planetary zero reference and never uses daylight saving time. Provinces and settlements may adopt different fixed UTC offsets; a settlement offset overrides its province offset.\",\"calendar\":{\"months_per_year\":11,\"days_per_month\":30,\"common_civil_year_days\":330,\"astronomical_year_days\":330.15,\"earth_equivalent_year_days\":365.2422,\"leap_interval_years\":7,\"leap_rule\":\"Every year divisible by 7 has one intercalary leap day after Month 11. The leap day is not a twelfth month and does not make any month longer than 30 days.\",\"civil_average_days_per_year\":330.14285714285717,\"duration_conversion\":{\"earth_days_per_universal_day\":1.1062916855974558,\"universal_days_per_earth_day\":0.9039207408125347}},\"utc\":{\"zero_meridian\":\"UTC at 0\u00b0 longitude\",\"daylight_saving_time\":false,\"default_offset_minutes\":0,\"longitude_derivation\":\"When no province or settlement rule exists, derive the fixed offset by rounding longitude to the nearest 15\u00b0 and assigning one UTC hour per 15\u00b0.\",\"resolution_precedence\":[\"settlement fixed offset\",\"province fixed offset\",\"explicit encounter offset\",\"longitude-derived fixed offset\",\"UTC\"]},\"coordinate_lines\":{\"meridians\":[{\"longitude\":-180,\"line\":\"180\u00b0 W / \u2212180\u00b0\",\"name\":\"Thalunesh's Reversed Track\",\"reference_utc_offset_minutes\":-720},{\"longitude\":-150,\"line\":\"150\u00b0 W\",\"name\":\"Freyseth's Crossroads Meridian\",\"reference_utc_offset_minutes\":-600},{\"longitude\":-120,\"line\":\"120\u00b0 W\",\"name\":\"Nefarokir's Funeral Meridian\",\"reference_utc_offset_minutes\":-480},{\"longitude\":-90,\"line\":\"90\u00b0 W\",\"name\":\"Eirzunet's Shadow Meridian\",\"reference_utc_offset_minutes\":-360},{\"longitude\":-60,\"line\":\"60\u00b0 W\",\"name\":\"Bastveig's Tidegate Meridian\",\"reference_utc_offset_minutes\":-240},{\"longitude\":-30,\"line\":\"30\u00b0 W\",\"name\":\"Horundar's Storm Meridian\",\"reference_utc_offset_minutes\":-120},{\"longitude\":0,\"line\":\"0\u00b0\",\"name\":\"UTC\",\"reference_utc_offset_minutes\":0},{\"longitude\":30,\"line\":\"30\u00b0 E\",\"name\":\"Raeshkul's Calculation Meridian\",\"reference_utc_offset_minutes\":120},{\"longitude\":60,\"line\":\"60\u00b0 E\",\"name\":\"Sokhivar's Sunroad Meridian\",\"reference_utc_offset_minutes\":240},{\"longitude\":90,\"line\":\"90\u00b0 E\",\"name\":\"Ishtanora's Hearth Meridian\",\"reference_utc_offset_minutes\":360},{\"longitude\":120,\"line\":\"120\u00b0 E\",\"name\":\"Marduthor's Deepforge Meridian\",\"reference_utc_offset_minutes\":480},{\"longitude\":150,\"line\":\"150\u00b0 E\",\"name\":\"Valkhamesh's Thunder Meridian\",\"reference_utc_offset_minutes\":600}],\"parallels\":[{\"latitude\":60,\"line\":\"60\u00b0 N\",\"name\":\"Fleysetl's Northern Underworld Gate\"},{\"latitude\":25,\"line\":\"25\u00b0 N\",\"name\":\"Raeshkul's Thoughtline\"},{\"latitude\":0,\"line\":\"0\u00b0\",\"name\":\"Equator\"},{\"latitude\":-30,\"line\":\"30\u00b0 S\",\"name\":\"Bastveg's Deepwater Passage\"},{\"latitude\":-65,\"line\":\"65\u00b0 S\",\"name\":\"Thoryn-Rahek's Southern Underworld Gate\"}]},\"location_timezone_contract\":{\"province_fields\":[\"province_id\",\"province_name\",\"province_utc_offset_minutes\"],\"settlement_fields\":[\"settlement_id\",\"settlement_name\",\"settlement_utc_offset_minutes\"],\"optional_fields\":[\"semantic_id\",\"longitude\",\"latitude\",\"timezone_id\"],\"rule\":\"A settlement can observe a different fixed UTC offset than other settlements in the same province. Never overwrite a settlement override with the province default.\"},\"encounter_relevance\":[\"Resolve the encounter\u2019s local date and clock time from the shared UTC world time and the settlement-or-province fixed offset.\",\"Use local daypart to determine schedules, open services, witnesses, patrol changes, visibility, travel traffic, and plausible encounter openings.\",\"Store both UTC and local time in exported encounters so events remain chronologically comparable across provinces.\",\"When an encounter crosses a time-zone boundary, store both offsets and the local-clock shift; a clock shift changes schedules, not elapsed travel duration.\",\"No ancestry, deity, class, or alignment automatically determines whether a creature is nocturnal or active at a given time.\"],\"encounter_dayparts\":[{\"id\":\"deep-night\",\"name\":\"Deep Night\",\"start_hour\":0,\"end_hour\":4,\"visibility\":\"dark\",\"schedule_state\":\"sleep cycle, night watch, covert movement, or nocturnal activity\"},{\"id\":\"dawn\",\"name\":\"Dawn\",\"start_hour\":4,\"end_hour\":7,\"visibility\":\"dim-to-growing\",\"schedule_state\":\"watch change, opening gates, early labor, prayer, and departing travelers\"},{\"id\":\"morning\",\"name\":\"Morning\",\"start_hour\":7,\"end_hour\":12,\"visibility\":\"daylight\",\"schedule_state\":\"markets, work shifts, travel, patrols, and public services becoming active\"},{\"id\":\"midday\",\"name\":\"Midday\",\"start_hour\":12,\"end_hour\":14,\"visibility\":\"bright\",\"schedule_state\":\"peak public movement, meals, exchanges, and exposed travel\"},{\"id\":\"afternoon\",\"name\":\"Afternoon\",\"start_hour\":14,\"end_hour\":18,\"visibility\":\"daylight\",\"schedule_state\":\"active work, return journeys, deliveries, and institutional business\"},{\"id\":\"dusk\",\"name\":\"Dusk\",\"start_hour\":18,\"end_hour\":21,\"visibility\":\"fading\",\"schedule_state\":\"closing gates and shops, returning workers, evening rites, and predators becoming active\"},{\"id\":\"night\",\"name\":\"Night\",\"start_hour\":21,\"end_hour\":24,\"visibility\":\"dark\",\"schedule_state\":\"reduced public access, guarded routes, nightlife, smuggling, and nocturnal movement\"}]}}");
